class Solution {
public:
    vector<int> maxTargetNodes(vector<vector<int>>& edges1, vector<vector<int>>& edges2) {
        int n = edges1.size() + 1;
        int m = edges2.size() + 1;

        auto getParity = [](const vector<vector<int>>& edges, int size) {
            vector<vector<int>> adj(size);
            for (const auto& e : edges) {
                adj[e[0]].push_back(e[1]);
                adj[e[1]].push_back(e[0]);
            }
            vector<int> parity(size, -1);
            parity[0] = 0;
            vector<int> st = {0};
            int evenCnt = 1;
            while (!st.empty()) {
                int u = st.back();
                st.pop_back();
                for (int v : adj[u]) {
                    if (parity[v] == -1) {
                        parity[v] = parity[u] ^ 1;
                        if (parity[v] == 0) evenCnt++;
                        st.push_back(v);
                    }
                }
            }
            return make_pair(parity, evenCnt);
        };

        auto [par1, even1] = getParity(edges1, n);
        auto [par2, even2] = getParity(edges2, m);

        int odd1 = n - even1;
        int odd2 = m - even2;
        int maxT2 = max(even2, odd2);

        vector<int> ans(n);
        for (int i = 0; i < n; ++i) {
            ans[i] = (par1[i] == 0 ? even1 : odd1) + maxT2;
        }
        return ans;
    }
};

class Solution {
    public int[] maxTargetNodes(int[][] edges1, int[][] edges2) {
        int n = edges1.length + 1;
        int m = edges2.length + 1;

        ParityResult r1 = getParity(edges1, n);
        ParityResult r2 = getParity(edges2, m);

        int odd1 = n - r1.evenCnt;
        int odd2 = m - r2.evenCnt;
        int maxT2 = Math.max(r2.evenCnt, odd2);

        int[] ans = new int[n];
        for (int i = 0; i < n; ++i) {
            ans[i] = (r1.parity[i] == 0 ? r1.evenCnt : odd1) + maxT2;
        }
        return ans;
    }

    private static class ParityResult {
        int[] parity;
        int evenCnt;
        ParityResult(int[] p, int c) { parity = p; evenCnt = c; }
    }

    private ParityResult getParity(int[][] edges, int size) {
        List<Integer>[] adj = new ArrayList[size];
        for (int i = 0; i < size; ++i) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        int[] parity = new int[size];
        Arrays.fill(parity, -1);
        parity[0] = 0;
        Deque<Integer> st = new ArrayDeque<>();
        st.push(0);
        int evenCnt = 1;
        while (!st.isEmpty()) {
            int u = st.pop();
            for (int v : adj[u]) {
                if (parity[v] == -1) {
                    parity[v] = parity[u] ^ 1;
                    if (parity[v] == 0) evenCnt++;
                    st.push(v);
                }
            }
        }
        return new ParityResult(parity, evenCnt);
    }
}

var maxTargetNodes = function(edges1, edges2) {
    const n = edges1.length + 1;
    const m = edges2.length + 1;

    const getParity = (edges, size) => {
        const adj = Array.from({ length: size }, () => []);
        for (const [u, v] of edges) {
            adj[u].push(v);
            adj[v].push(u);
        }
        const parity = new Int8Array(size).fill(-1);
        parity[0] = 0;
        const st = [0];
        let evenCnt = 1;
        while (st.length > 0) {
            const u = st.pop();
            for (const v of adj[u]) {
                if (parity[v] === -1) {
                    parity[v] = parity[u] ^ 1;
                    if (parity[v] === 0) evenCnt++;
                    st.push(v);
                }
            }
        }
        return { parity, evenCnt };
    };

    const { parity: par1, evenCnt: even1 } = getParity(edges1, n);
    const { parity: par2, evenCnt: even2 } = getParity(edges2, m);

    const odd1 = n - even1;
    const odd2 = m - even2;
    const maxT2 = Math.max(even2, odd2);

    const ans = new Array(n);
    for (let i = 0; i < n; i++) {
        ans[i] = (par1[i] === 0 ? even1 : odd1) + maxT2;
    }
    return ans;
};
